package com.stockflow.document.adapter.out.http;
import tools.jackson.databind.ObjectMapper; import com.stockflow.document.application.*; import com.stockflow.shared.config.MindeeProperties; import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.*; import java.io.*; import java.net.*; import java.net.http.HttpClient; import java.time.Duration; import java.util.*; import static org.assertj.core.api.Assertions.*;
class MindeeV2FinancialDocumentClientTest {
 HttpServer server; String auth; String jobAuth; String multipart;
 void start() throws Exception {server=HttpServer.create(new InetSocketAddress("localhost",0),0); server.createContext("/v2/inferences/enqueue",x->{auth=x.getRequestHeaders().getFirst("Authorization");multipart=new String(x.getRequestBody().readAllBytes());reply(x,200,"{\"job\":{\"id\":\"job-1\"}}");});server.createContext("/v2/jobs/job-1",x->{jobAuth=x.getRequestHeaders().getFirst("Authorization");reply(x,200,"{\"job\":{\"status\":\"SUCCESS\",\"inference_id\":\"inf-1\"}}");});server.createContext("/v2/inferences/inf-1",x->reply(x,200,"{\"inference\":{\"result\":{\"fields\":{\"supplier_name\":{\"value\":\"ACME\"},\"invoice_number\":{\"value\":\"INV-1\"},\"total_amount\":{\"value\":\"12.50\"}},\"locale\":{\"currency\":\"USD\"}}}}"));server.start();}
 @AfterEach void stop(){if(server!=null)server.stop(0);} @Test void sendsRawKeyMultipartAndMapsLocale() throws Exception {start();var p=new MindeeProperties("key","00000000-0000-0000-0000-000000000001","http://localhost:"+server.getAddress().getPort(),Duration.ofSeconds(2));var c=new MindeeV2FinancialDocumentClient(p,HttpClient.newHttpClient(),new ObjectMapper());var r=c.extract(new FinancialDocumentExtractionPort.ExtractionRequest(UUID.randomUUID(),UUID.randomUUID(),"invoice.pdf","application/pdf",new ByteArrayInputStream("pdf".getBytes())));assertThat(auth).isEqualTo("key");assertThat(jobAuth).isEqualTo("key");assertThat(multipart).contains("name=\"model_id\"","name=\"file\"");assertThat(r.supplierName()).contains("ACME");assertThat(r.currency()).contains("USD");assertThat(r.totalAmount()).hasValueSatisfying(x->assertThat(x).isEqualByComparingTo("12.50"));}
 @Test void missingConfigurationFailsBeforeHttp(){var p=new MindeeProperties("","","http://127.0.0.1:1",Duration.ofSeconds(1));var c=new MindeeV2FinancialDocumentClient(p,null,new ObjectMapper());assertThatThrownBy(()->c.extract(new FinancialDocumentExtractionPort.ExtractionRequest(UUID.randomUUID(),UUID.randomUUID(),"x.pdf","application/pdf",new ByteArrayInputStream(new byte[]{1})))).isInstanceOf(MindeeConfigurationException.class);}
 @Test void mapsRealProviderProcessedJobAndNestedLocale() throws Exception {server=HttpServer.create(new InetSocketAddress("localhost",0),0);server.createContext("/v2/inferences/enqueue",x->reply(x,200,"{\"job\":{\"id\":\"job-2\"}}"));server.createContext("/v2/jobs/job-2",x->reply(x,200,"{\"job\":{\"status\":\"Processed\",\"result_url\":\"http://localhost:"+server.getAddress().getPort()+"/result/job-2\"}}"));server.createContext("/result/job-2",x->reply(x,200,"{\"inference\":{\"result\":{\"fields\":{\"supplier_name\":{\"value\":\"Demo Supplies LLC\"},\"invoice_number\":{\"value\":\"DEMO-2026-001\"},\"date\":{\"value\":\"2026-11-11\"},\"total_amount\":{\"value\":123.45},\"locale\":{\"fields\":{\"currency\":{\"value\":\"USD\"}}}}}}}"));server.start();var p=new MindeeProperties("key","model","http://localhost:"+server.getAddress().getPort(),Duration.ofSeconds(2));var c=new MindeeV2FinancialDocumentClient(p,HttpClient.newHttpClient(),new ObjectMapper());var r=c.extract(new FinancialDocumentExtractionPort.ExtractionRequest(UUID.randomUUID(),UUID.randomUUID(),"invoice.png","image/png",new ByteArrayInputStream(new byte[]{1})));assertThat(r.supplierName()).contains("Demo Supplies LLC");assertThat(r.invoiceNumber()).contains("DEMO-2026-001");assertThat(r.currency()).contains("USD");assertThat(r.totalAmount()).hasValueSatisfying(x->assertThat(x).isEqualByComparingTo("123.45"));}
 static void reply(com.sun.net.httpserver.HttpExchange x,int s,String body)throws IOException{x.sendResponseHeaders(s,body.length());try(var o=x.getResponseBody()){o.write(body.getBytes());}}
}
